def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    # Extend the matching diagonal segment in both directions.
                    for sr, sc in ((-dr, -dc), (dr, dc)):
                        rr, cc = r, c
                        while 0 <= rr < h and 0 <= cc < w:
                            if out[rr][cc] == bg:
                                out[rr][cc] = color
                            rr += sr
                            cc += sc
    return out
